import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root group for this node
  const root = new Group();

  // ---- Textured Plane (billboard) ----
  const atlasRect = { width: 512, height: 320 };
  const aspect = atlasRect.width / atlasRect.height; // 1.6
  const planeWidth = aspect; // 1.6 units
  const planeHeight = 1; // 1 unit
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial();

  // Load texture asynchronously; material will update when ready
  const imgUrl = config.imageUrl ?? config.meshUrl ?? null;
  if (imgUrl) {
    ctx.textureLoader.loadTexture(imgUrl).then((tex) => {
      material.map = texture(tex);
      material.needsUpdate = true;
    });
  }

  const plane = new Mesh(geometry, material);
  // Simple billboard: copy camera orientation each frame
  plane.onBeforeRender = (_, __, camera) => {
    plane.quaternion.copy(camera.quaternion);
  };
  root.add(plane);

  // ---- Text Content ----
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];
  const textGroup = new Group();

  const colors = config.intent?.visualSpec?.colors ?? {};
  const defaultColor = colors.paper ?? '#e8ecf2';

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: defaultColor,
      align: 'center',
    });
    // Center text on the plane, slightly in front to avoid Z‑fighting
    txt.position.set(0, 0, 0.01);
    textGroup.add(txt);
  }
  root.add(textGroup);

  // ---- Cinematic Primitives (if any) ----
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const inst = ctx.primitives[prim.name](root, prim.params);
      primitiveInstances.push(inst);
    }
  }

  // ---- Event Handlers (none in this spec) ----
  root.userData.handlers = {};

  // ---- Cleanup ----
  const baseCleanup = () => {
    geometry.dispose();
    material.dispose();

    // Dispose any textures that were set on the material
    if (material.map && material.map.isTexture) {
      material.map.dispose();
    }

    // Dispose text resources
    textGroup.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose();
        obj.material?.dispose();
      }
    });
  };

  root.userData.cleanup = () => {
    // Clean primitives first
    for (const inst of primitiveInstances) {
      if (inst?.cleanup) inst.cleanup();
    }
    baseCleanup();
  };

  return root;
}
